  !SUPABASE_URL.includes("TU-PROYECTO") &&
  SUPABASE_ANON_KEY &&
  !SUPABASE_ANON_KEY.includes("TU_ANON_KEY");

// Cliente oficial. Se crea siempre (no rompe nada crearlo con valores
// de ejemplo); solo se usa de verdad cuando isSupabaseConfigured es true.
const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

const toCamel = (s) => s.replace(/_([a-z])/g, (_, c) => c.toUpperCase());
const toSnake = (s) => s.replace(/[A-Z]/g, (c) => "_" + c.toLowerCase());
const rowToCamel = (row) => {
  const out = {};
  for (const k in row) out[toCamel(k)] = row[k];
  return out;
};
const objToSnake = (obj) => {
  const out = {};
  for (const k in obj) out[toSnake(k)] = obj[k];
  return out;
};

// Las fotos y PDF (facturas, comprobantes...) se guardan dentro de la fila como texto y
// pesan mucho: si se bajaran todos al abrir la app, la lectura tarda más de lo que
// Supabase permite y falla. Por eso estas columnas se leen aparte, solo cuando se abre
// el archivo: al cargar, en su lugar queda una marca "diferido:tabla:columna:id".
const ARCHIVOS_DIFERIDOS = {
  compras_facturas: ["archivo"],
  facturas_varias: ["archivo"],
  documentos_cobros: ["archivo"],
  ingresos: ["archivo", "aviso_pago_archivo"],
  facturas_venta_proyectadas: ["archivo"],
  cobros_socios: ["archivo"],
};
const MARCA_DIFERIDO = "diferido:";
const esArchivoDiferido = (v) => typeof v === "string" && v.startsWith(MARCA_DIFERIDO);
const cacheArchivosDiferidos = new Map();
// Devuelve el archivo real (data URL) de una marca diferida; cualquier otro valor tal cual.
async function resolverArchivo(valor) {
  if (!esArchivoDiferido(valor)) return valor;
  if (cacheArchivosDiferidos.has(valor)) return cacheArchivosDiferidos.get(valor);
  const [, tabla, columna, id] = valor.split(":");
  const { data, error } = await supabase.from(tabla).select(columna).eq("id", Number(id)).single();
  if (error) throw new Error(`No se pudo bajar el archivo: ${error.message}`);
  cacheArchivosDiferidos.set(valor, data[columna]);
  return data[columna];
}

async function sbSelect(table) {
  const diferidas = ARCHIVOS_DIFERIDOS[table];
  if (diferidas) {
    const { data, error } = await supabase.rpc("listar_sin_archivos", { tabla: table, excluir: diferidas });
    if (error) throw new Error(`No se pudo leer "${table}": ${error.message}`);
    return (data || []).map((fila) => {
      const f = { ...fila };
      diferidas.forEach((c) => {
        const tiene = f[`tiene_${c}`];
        delete f[`tiene_${c}`];
        f[c] = tiene ? `${MARCA_DIFERIDO}${table}:${c}:${f.id}` : null;
      });
      return rowToCamel(f);
    });
  }
  const { data, error } = await supabase.from(table).select("*").order("id", { ascending: true });
  if (error) throw new Error(`No se pudo leer "${table}": ${error.message}`);
  return data.map(rowToCamel);
}

// "Failed to fetch" = se cortó la conexión antes de que llegara la respuesta (señal, wifi).
const esErrorDeConexion = (error) => /failed to fetch|networkerror|load failed|network request failed/i.test(error?.message || "");
const mensajeDeError = (error) => (esErrorDeConexion(error)
  ? "se cortó la conexión a internet y el cambio no se guardó. Revisá la señal y probá de nuevo."
  : error.message);
// Para operaciones que se pueden repetir sin duplicar nada (modificar, borrar):
// si se corta la conexión, se reintenta solo un par de veces antes de avisar.
async function conReintento(operacion) {
  let resultado = await operacion();
  for (const espera of [800, 2000]) {
    if (!esErrorDeConexion(resultado.error)) break;
    await new Promise((r) => setTimeout(r, espera));
    resultado = await operacion();
  }
  return resultado;
}

async function sbInsert(table, obj) {
  // Si se copia un archivo que todavía no se bajó (ej. la factura de una factura de
  // venta futura que pasa al cobro), se baja antes para guardar el archivo real.
  const conArchivos = { ...obj };
  for (const [k, v] of Object.entries(conArchivos)) {
    if (esArchivoDiferido(v)) conArchivos[k] = await resolverArchivo(v);
  }
  obj = conArchivos;
  const { data, error } = await supabase.from(table).insert(objToSnake(obj)).select().single();
  if (error) throw new Error(`No se pudo guardar en "${table}": ${mensajeDeError(error)}`);
  return rowToCamel(data);
}

async function sbUpdate(table, id, patch) {
  // Un archivo que sigue "diferido" (no se bajó ni se cambió) no se toca.
  patch = Object.fromEntries(Object.entries(patch).filter(([, v]) => !esArchivoDiferido(v)));
  // En las tablas con archivos no se pide la fila de vuelta (traería el archivo entero):
  // devuelve null y quien llama combina el cambio con lo que ya tenía.
  if (ARCHIVOS_DIFERIDOS[table]) {
    const { error } = await conReintento(() => supabase.from(table).update(objToSnake(patch)).eq("id", id));
    if (error) throw new Error(`No se pudo actualizar "${table}": ${mensajeDeError(error)}`);
    return null;
  }
  const { data, error } = await conReintento(() => supabase.from(table).update(objToSnake(patch)).eq("id", id).select().single());
  if (error) throw new Error(`No se pudo actualizar "${table}": ${mensajeDeError(error)}`);
  return rowToCamel(data);
}

async function sbDelete(table, id) {
  const { error } = await conReintento(() => supabase.from(table).delete().eq("id", id));
  if (error) throw new Error(`No se pudo eliminar en "${table}": ${mensajeDeError(error)}`);
}

function readFileAsDataURL(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

// Los comprobantes se guardan en la base como "data URL" (el archivo entero en
// texto). Los navegadores no dejan abrir una data URL directo en una pestaña nueva
// (el link no hace nada), así que se convierte a un archivo temporal del navegador
// (blob) y se abre ese — el PDF o la foto se ve con el visor normal.
function abrirArchivo(archivo) {
  if (!archivo) return;
  if (esArchivoDiferido(archivo)) {
    // La ventana se abre ya (si se abre después de esperar la descarga, el celular la
    // bloquea) y se completa cuando llega el archivo.
    const ventana = window.open("", "_blank");
    if (ventana) ventana.document.write("<p style='font-family:sans-serif;padding:16px'>Cargando archivo…</p>");
    resolverArchivo(archivo)
      .then((real) => {
        const url = dataUrlABlobUrl(real);
        if (!url) throw new Error("vacío");
        if (ventana) ventana.location.href = url; else window.open(url, "_blank");
      })
      .catch(() => {
        if (ventana) ventana.close();
        alert("No se pudo abrir el archivo. Revisá la conexión y probá de nuevo.");
      });
    return;
  }
  if (!archivo.startsWith("data:")) {
    window.open(archivo, "_blank", "noopener");
    return;
  }
  const url = dataUrlABlobUrl(archivo);
  if (!url) { alert("No se pudo abrir el archivo."); return; }
  const ventana = window.open(url, "_blank");
  if (!ventana) alert("El navegador bloqueó la ventana nueva. Permití las ventanas emergentes para esta página y volvé a intentar.");
}
// Data URL → archivo temporal del navegador (blob) que se puede abrir en una pestaña.
function dataUrlABlobUrl(archivo) {
  if (!archivo || !archivo.startsWith("data:")) return archivo || null;
  try {
    const coma = archivo.indexOf(",");
    const meta = archivo.slice(5, coma);
    const datos = archivo.slice(coma + 1);
    const mime = meta.split(";")[0] || "application/octet-stream";
    let bytes;
    if (meta.includes(";base64")) {
      const bin = atob(datos);
      bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    } else {
      bytes = new TextEncoder().encode(decodeURIComponent(datos));
    }
    const url = URL.createObjectURL(new Blob([bytes], { type: mime }));
    // Se libera después de un rato largo, cuando el visor ya terminó de cargarlo.
    setTimeout(() => URL.revokeObjectURL(url), 10 * 60 * 1000);
    return url;
  } catch {
    return null;
  }
}

// El navegador interno de algunas apps (y celulares viejos) no tiene
// navigator.clipboard — ahí se copia con el método clásico de un textarea oculto.
async function copiarAlPortapapeles(texto) {
  try {
    await navigator.clipboard.writeText(texto);
    return true;
  } catch {
    const ta = document.createElement("textarea");
    ta.value = texto;
    ta.setAttribute("readonly", "");
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    const ok = document.execCommand("copy");
    document.body.removeChild(ta);
    return ok;
  }
}

function BotonCopiarMensaje({ texto, label }) {
  const [estado, setEstado] = useState(null);
  async function copiar() {
    const ok = await copiarAlPortapapeles(texto);
    setEstado(ok ? "copiado" : "error");
    setTimeout(() => setEstado(null), 2500);
  }
  return (
    <button
      type="button"
      onClick={copiar}
      className={`flex items-center gap-1.5 rounded-md border px-3 py-2 text-sm font-semibold ${
        estado === "copiado" ? "border-emerald-300 bg-emerald-50 text-emerald-700" : "border-stone-300 bg-white text-slate-700 hover:bg-stone-50"
      }`}
    >
      {estado === "copiado" ? <Check size={15} /> : <Copy size={15} />}
      {estado === "copiado" ? "¡Copiado! Pegalo en WhatsApp" : estado === "error" ? "No se pudo copiar" : label}
    </button>
  );
}

// Ida y vuelta del alta por WhatsApp: copiar el mensaje para la persona que entra
// y, cuando contesta, pegar su respuesta para que el formulario se complete solo.
function AsistenteAltaWhatsApp({ onCompletar }) {
  const [pegando, setPegando] = useState(false);
  const [texto, setTexto] = useState("");
  const [resultado, setResultado] = useState(null);

  function completar() {
    const r = parsearRespuestaAltaPersonal(texto);
    onCompletar(r.datos);
    setResultado(r);
    setPegando(false);
    setTexto("");
  }

  return (
    <div className="mb-4 space-y-2 rounded-lg border border-dashed border-stone-300 bg-stone-50 p-3">
      <div className="flex flex-wrap items-center gap-2">
        <BotonCopiarMensaje texto={MENSAJE_ALTA_PERSONAL} label="Copiar mensaje para WhatsApp" />
        <button
          type="button"
          onClick={() => { setPegando((v) => !v); setResultado(null); }}
          className="flex items-center gap-1.5 rounded-md border border-stone-300 bg-white px-3 py-2 text-sm font-semibold text-slate-700 hover:bg-stone-50"
        >
          <ClipboardCheck size={15} /> Pegar respuesta
        </button>
      </div>
      <div className="text-xs text-slate-500">
        Copiá el mensaje y mandáselo a quien entra. Cuando te conteste, copiá su respuesta, tocá "Pegar respuesta" y el formulario se completa solo.
      </div>

      {pegando && (
        <div className="space-y-2">
          <textarea
            value={texto}
            onChange={(e) => setTexto(e.target.value)}
            rows={8}
            autoFocus
            placeholder="Pegá acá el mensaje que te mandó por WhatsApp..."
            className={inputCls}
          />
          <div className="flex gap-2">
            <button
              type="button"
              onClick={completar}
              disabled={!texto.trim()}
              className="rounded-md bg-slate-900 px-4 py-2 text-sm font-semibold text-white hover:bg-slate-700 disabled:cursor-not-allowed disabled:opacity-40"
            >
              Completar formulario
            </button>
            <button type="button" onClick={() => { setPegando(false); setTexto(""); }} className={btnGhost}>Cancelar</button>
          </div>
        </div>
      )}

      {resultado && (
        <div className={`space-y-1 rounded-md border px-3 py-2 text-xs ${resultado.completados.length > 0 ? "border-emerald-200 bg-emerald-50 text-emerald-800" : "border-amber-200 bg-amber-50 text-amber-800"}`}>
          {resultado.completados.length > 0 ? (
            <div>
              <span className="font-semibold">Se completaron {resultado.completados.length} datos:</span> {resultado.completados.join(", ")}. Revisalos antes de guardar.
            </div>
          ) : (
            <div className="font-semibold">No encontré datos en el texto. Fijate que sea su respuesta al mensaje (con "Nombre:", "DNI:", etc.).</div>
          )}
          {resultado.sinReconocer.length > 0 && (
            <div className="text-amber-800">No pude entender: {resultado.sinReconocer.join(", ")} — cargalos a mano.</div>
          )}
          <div className="text-slate-600">Las fotos (la suya y las del DNI) guardalas del WhatsApp y subilas abajo.</div>
        </div>
      )}
    </div>
  );
}

