const inputCls = "rounded-md border border-stone-300 bg-white px-3 py-2 text-sm text-slate-800 outline-none focus:border-amber-500 focus:ring-2 focus:ring-amber-500/30";
const btnGhost = "rounded-md border border-slate-300 px-2.5 py-1 text-xs font-semibold text-slate-700 hover:bg-stone-100";
// Versión compacta de btnGhost para tablas densas (Gastos y Facturas), donde varios
// botones por fila necesitan entrar en poco alto sin forzar la fila a dos líneas.
const btnGhostSm = "rounded-md border border-slate-300 px-1.5 py-0.5 text-[10px] font-semibold text-slate-700 hover:bg-stone-100";
// Botón amarillo de "agregar/cargar" — se repetía a mano en cada pestaña.
const btnPrimary = "flex items-center gap-1 rounded-md bg-amber-500 px-3 py-2 text-sm font-semibold text-slate-900 hover:bg-amber-400";

// Campo de plata: mientras escribís va agregando puntos de miles en vivo
// (1 -> 10 -> 100 -> 1.000), como en una caja registradora — y Borrar saca un
// dígito genuino cada vez (antes quedaba "pegado" en el ",00" fijo del final,
// así que Borrar no achicaba el número).
// Funciona tanto con formularios controlados (value+onChange) como con FormData (name).
// Lista de retenciones de un cobro: tipo + monto, con el total retenido y lo que
// entra a la cuenta. Controlado: value es el array [{ tipo, monto }].
function EditorRetenciones({ value, onChange, montoFactura }) {
  const lista = Array.isArray(value) ? value : [];
  const total = lista.reduce((s, r) => s + (Number(r.monto) || 0), 0);
  const cambiar = (idx, patch) => onChange(lista.map((r, i) => (i === idx ? { ...r, ...patch } : r)));
  // Renglones en los que se está escribiendo el nombre de una retención nueva.
  const [escribiendo, setEscribiendo] = useState(() => new Set());
  const opciones = [...TIPOS_RETENCION, ...tiposRetencionExtra.lista.filter((t) => !TIPOS_RETENCION.includes(t))];
  return (
    <div className="space-y-1.5 rounded-md border border-stone-200 bg-stone-50/60 p-2.5">
      <div className="text-[11px] font-semibold uppercase tracking-wide text-slate-500">Retenciones (si al cobrar te retuvieron algo)</div>
      {lista.map((r, idx) => {
        const esNueva = escribiendo.has(idx) || (r.tipo && !opciones.includes(r.tipo));
        return (
          <div key={idx} className="flex flex-wrap items-center gap-2">
            {esNueva ? (
              <span className="flex items-center gap-1">
                <input
                  autoFocus={escribiendo.has(idx)}
                  value={r.tipo}
                  onChange={(e) => cambiar(idx, { tipo: e.target.value })}
                  placeholder="Nombre, ej: Fondo minero"
                  className={`${inputCls} w-52 text-xs`}
                />
                <button type="button" onClick={() => { setEscribiendo((prev) => { const n = new Set(prev); n.delete(idx); return n; }); cambiar(idx, { tipo: "IVA" }); }} title="Elegir de la lista" className="text-[10px] text-slate-500 underline hover:text-slate-800">lista</button>
              </span>
            ) : (
              <select
                value={r.tipo}
                onChange={(e) => {
                  if (e.target.value === "__otra") {
                    setEscribiendo((prev) => new Set(prev).add(idx));
                    cambiar(idx, { tipo: "" });
                  } else {
                    cambiar(idx, { tipo: e.target.value });
                  }
                }}
                className={`${inputCls} w-52 text-xs`}
              >
                {opciones.map((t) => <option key={t} value={t}>Retención de {t}</option>)}
                <option value="__otra">Otra retención (escribir nombre)…</option>
              </select>
            )}
            <MoneyInput value={r.monto} onChange={(v) => cambiar(idx, { monto: v })} puntoDecimalAlPegar className={`${inputCls} w-40 text-xs`} />
            <button type="button" onClick={() => onChange(lista.filter((_, i) => i !== idx))} title="Quitar retención" className="text-slate-400 hover:text-rose-600"><X size={14} /></button>
          </div>
        );
      })}
      <div className="flex flex-wrap items-center justify-between gap-2">
        <button type="button" onClick={() => onChange([...lista, { tipo: "IVA", monto: 0 }])} className={btnGhostSm}>
          <span className="flex items-center gap-1"><Plus size={11} /> Agregar retención</span>
        </button>
        {total > 0 && (
          <span className="text-xs text-slate-600">
            Te retuvieron <span className="font-mono font-semibold text-amber-700">{fmtARS(total)}</span>
            {montoFactura > 0 && <> · entra a la cuenta <span className="font-mono font-semibold text-emerald-700">{fmtARS(montoFactura - total)}</span></>}
          </span>
        )}
      </div>
    </div>
  );
}

// Percepciones que el proveedor cobró en su factura (renglones "Percepción IIBB",
// "Per IB SJ", "Percepción IVA"...). Se completan solas al subir la factura en PDF.
